function translateCore(value, locale) {
  const catalogue = locale === "en" ? EN : DE;
  if (catalogue.has(value)) return catalogue.get(value);
  if (locale !== "en") return value;
  for (const [pattern, replacement] of EN_PATTERNS) {
    if (pattern.test(value)) return value.replace(pattern, replacement);
  }
  let translated = value;
  for (const [source, replacement] of EN_FRAGMENTS) translated = translated.replaceAll(source, replacement);
  return translated;
}

export function translateText(rawValue, locale) {
  if (typeof rawValue !== "string" || !rawValue.trim()) return rawValue;
  const leading = rawValue.match(/^\s*/)?.[0] ?? "";
  const trailing = rawValue.match(/\s*$/)?.[0] ?? "";
  const core = rawValue.slice(leading.length, rawValue.length - trailing.length || undefined);
  return `${leading}${translateCore(core, locale)}${trailing}`;
}

export function translateAttribute(value, locale) {
  return translateText(value, locale);
}
